"""Painel de demonstração do ML (Streamlit, formato da Aula 12). Rode na raiz: python aplicar_painel_ml.py
Pré-requisito: aplicar_calendario_demanda.py já aplicado."""
from pathlib import Path

ARQUIVOS = {'ml/demanda.py': '"""Previsão de DEMANDA: quantos atendimentos reativos cada distrito deve ter na PRÓXIMA semana.\n\nPara planejar equipe (escalas, férias, estoque de lonas), não para alertar.\n\nAlvo: soma semanal de atendimentos REATIVOS por distrito (gold.ml_distrito_dia, 2015-2024).\nMomento da previsão: segunda-feira de manhã. Só entra o que já se sabe nessa hora: calendário,\nferiados da semana, chuva e atendimentos até o domingo anterior. A chuva da própria semana\nNÃO entra (a 1ª rodada usava; isso deixava o resultado otimista, porque ninguém sabe na\nsegunda quanto vai chover até domingo). A versão 0 continua no relatório só para comparação.\n\nVersões (cada uma acrescenta algo à anterior):\n  0 original: calendário + chuva da própria semana e da anterior (não usável na prática)\n  1 corrigida: calendário + chuva da semana anterior\n  2 + demanda das semanas anteriores (semana passada e média das últimas 4)\n  3 + chuva detalhada (maior chuva de um dia, dias com 30 mm ou mais, acumulado de 2 e 4 semanas)\n  4 + dois modelos: atendimentos ligados à chuva e os demais (vistorias etc.), somados no fim\n\nModelo: XGBoost com objetivo de CONTAGEM (Poisson).\nRégua: a média daquela semana do ano naquele distrito nos anos de treino (o "normal").\n\nRegras fixadas ANTES de rodar:\n  - a versão final é escolhida entre 1-4 pelo erro da validação cruzada NO TREINO\n    (TimeSeriesSplit), nunca pelo teste;\n  - ela é aprovada se errar pelo menos 10% menos que a régua (MAE) no teste 2022-2024.\nO teste das outras versões aparece só para mostrar quanto cada mudança ajudou.\n\nUso:\n    python -m ml.demanda             avaliação (versões, régua, veredito)\n    python -m ml.demanda --salvar    treina com todos os anos e salva em modelos/demanda.joblib\n    python -m ml.demanda --prever    previsão da semana atual por distrito -> gold.demanda_previsao\n    Demonstração com uma semana já conhecida (o modelo não pode ter visto esse ano):\n    python -m ml.demanda --salvar --ate-ano 2023 && python -m ml.demanda --prever --data 2024-05-20\n\nNa previsão, usa a versão 3 quando há atendimentos da semana passada no banco; se os dados da\nDefesa Civil estiverem atrasados, cai para a versão 1 (só calendário e chuva) e avisa na tela.\n"""\n\nimport argparse\nfrom datetime import date, datetime, timedelta, timezone\nfrom pathlib import Path\n\nimport joblib\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.base import clone\nfrom sklearn.model_selection import GridSearchCV, TimeSeriesSplit\nfrom xgboost import XGBRegressor\n\nfrom dominio.distritos import nome_distrito\nfrom dominio.feriados import feriados_recife\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\n\nSAIDA = Path(__file__).resolve().parents[1] / "analises" / "ml" / "saida"\nTREINO, TESTE = range(2015, 2022), range(2022, 2025)\nGRADE = {"n_estimators": [200, 400], "max_depth": [3, 5], "learning_rate": [0.05, 0.1]}\nGANHO_MINIMO = 0.10\nCHUVA_FORTE_MM = 30\nAVALIACAO = SAIDA / "demanda_avaliacao.joblib"\nPASTA_MODELOS = Path(__file__).resolve().parents[1] / "modelos"\nCOMPLETA, REDUZIDA = "3 + chuva detalhada", "1 corrigida"     # completa: escolhida na avaliação\n\nCALENDARIO = ["distrito_codigo", "semana", "mes", "feriados"]\nDEMANDA_ANTERIOR = ["atend_ant_1", "atend_media_4"]\nCHUVA_DETALHADA = ["chuva_max_dia_ant_mm", "dias_chuva_forte_ant", "chuva_2sem_mm", "chuva_4sem_mm"]\nPOR_TIPO_ANTERIOR = ["chuva_ant_1", "chuva_media_4", "outros_ant_1", "outros_media_4"]\n\nORIGINAL = "0 original (chuva da própria semana)"\nVERSOES = {\n    ORIGINAL: (CALENDARIO + ["chuva_semana_mm", "chuva_semana_anterior_mm"], ["atendimentos"]),\n    "1 corrigida": (CALENDARIO + ["chuva_semana_anterior_mm"], ["atendimentos"]),\n    "2 + demanda anterior": (CALENDARIO + ["chuva_semana_anterior_mm"] + DEMANDA_ANTERIOR, ["atendimentos"]),\n    "3 + chuva detalhada": (CALENDARIO + ["chuva_semana_anterior_mm"] + DEMANDA_ANTERIOR + CHUVA_DETALHADA,\n                            ["atendimentos"]),\n    "4 + chuva e outros separados": (CALENDARIO + ["chuva_semana_anterior_mm"] + DEMANDA_ANTERIOR + CHUVA_DETALHADA\n                                     + POR_TIPO_ANTERIOR, ["atend_chuva", "atend_outros"]),\n}\nENTRADAS = VERSOES["1 corrigida"][0]          # compatibilidade com quem importava ENTRADAS\n\n\ndef _anterior(s, coluna, semanas):\n    """Valor de `semanas` semanas atrás no mesmo distrito; vazio se houver buraco na série."""\n    valores = s.set_index(["distrito_codigo", "inicio"])[coluna]\n    chave = pd.MultiIndex.from_arrays([s["distrito_codigo"], s["inicio"] - pd.Timedelta(days=7 * semanas)])\n    return pd.Series(valores.reindex(chave).to_numpy(), index=s.index)\n\n\ndef semanal(df):\n    """Tabela distrito x dia -> distrito x semana (segunda a domingo) com as entradas de cada versão."""\n    df = df.copy()\n    df["data"] = pd.to_datetime(df["data"])\n    if "atendimentos_chuva" not in df:\n        df["atendimentos_chuva"] = 0\n    df["inicio"] = df["data"] - pd.to_timedelta(df["data"].dt.day_of_week, unit="D")\n    feriados = set()\n    for ano in range(df["data"].dt.year.min(), df["data"].dt.year.max() + 1):\n        feriados |= {pd.Timestamp(d) for d in feriados_recife(ano)}\n    df["feriado"] = df["data"].isin(feriados)\n    df["chuva_forte"] = df["chuva_dia_mm"] >= CHUVA_FORTE_MM\n    s = df.groupby(["distrito_codigo", "inicio"]).agg(\n        atendimentos=("atendimentos_reativos", "sum"), atend_chuva=("atendimentos_chuva", "sum"),\n        chuva_semana_mm=("chuva_dia_mm", "sum"), chuva_max_dia_mm=("chuva_dia_mm", "max"),\n        dias_chuva_forte=("chuva_forte", "sum"), feriados=("feriado", "sum"),\n        dias=("data", "size")).reset_index()\n    s = s[s["dias"] == 7].sort_values(["distrito_codigo", "inicio"]).reset_index(drop=True)\n    s["atend_chuva"] = s["atend_chuva"].clip(upper=s["atendimentos"])\n    s["atend_outros"] = s["atendimentos"] - s["atend_chuva"]\n\n    s["chuva_semana_anterior_mm"] = _anterior(s, "chuva_semana_mm", 1)\n    s["chuva_max_dia_ant_mm"] = _anterior(s, "chuva_max_dia_mm", 1)\n    s["dias_chuva_forte_ant"] = _anterior(s, "dias_chuva_forte", 1)\n    chuva = [_anterior(s, "chuva_semana_mm", k) for k in range(1, 5)]\n    s["chuva_2sem_mm"] = pd.concat(chuva[:2], axis=1).sum(axis=1, skipna=False)\n    s["chuva_4sem_mm"] = pd.concat(chuva, axis=1).sum(axis=1, skipna=False)\n    for coluna, nome in (("atendimentos", "atend"), ("atend_chuva", "chuva"), ("atend_outros", "outros")):\n        anteriores = [_anterior(s, coluna, k) for k in range(1, 5)]\n        s[f"{nome}_ant_1"] = anteriores[0]\n        s[f"{nome}_media_4"] = pd.concat(anteriores, axis=1).mean(axis=1)\n\n    s["semana"] = s["inicio"].dt.isocalendar().week.astype(int).clip(upper=52)\n    s["mes"] = s["inicio"].dt.month\n    s["ano"] = s["inicio"].dt.year\n    return s\n\n\ndef regua(treino, teste):\n    """O \'normal\': média daquela semana do ano naquele distrito, nos anos de treino."""\n    normal = treino.groupby(["distrito_codigo", "semana"])["atendimentos"].mean()\n    return teste.set_index(["distrito_codigo", "semana"]).index.map(normal).to_numpy(dtype=float)\n\n\ndef metricas(previsto, real):\n    ok = ~np.isnan(previsto)\n    p, r = previsto[ok], real[ok]\n    mae = float(np.mean(np.abs(p - r)))\n    wape = float(np.sum(np.abs(p - r)) / np.sum(r))\n    r2 = float(1 - np.sum((r - p) ** 2) / np.sum((r - r.mean()) ** 2))\n    return {"mae": mae, "wape": wape, "r2": r2}\n\n\ndef _ajustar(treino, entradas, alvo, grade):\n    busca = GridSearchCV(XGBRegressor(objective="count:poisson", tree_method="hist", random_state=42, n_jobs=-1),\n                         grade, scoring="neg_mean_absolute_error", cv=TimeSeriesSplit(4), n_jobs=1)\n    busca.fit(treino[entradas].astype(float), treino[alvo])\n    return busca.best_estimator_\n\n\ndef _versao(treino, teste, entradas, alvos, grade):\n    """Treina um modelo por alvo (a demanda é a soma deles); devolve previsão no teste,\n    erro da validação cruzada no treino e os modelos."""\n    modelos = [_ajustar(treino, entradas, a, grade) for a in alvos]\n    previsto = sum(m.predict(teste[entradas].astype(float)) for m in modelos)\n    erros = []\n    for i_tr, i_va in TimeSeriesSplit(4).split(treino):\n        tr, va = treino.iloc[i_tr], treino.iloc[i_va]\n        p = sum(clone(m).fit(tr[entradas].astype(float), tr[a]).predict(va[entradas].astype(float))\n                for m, a in zip(modelos, alvos))\n        erros.append(np.mean(np.abs(p - va["atendimentos"].to_numpy(dtype=float))))\n    return previsto, float(np.mean(erros)), modelos\n\n\ndef executar(s, grade=None, avisar=print, detalhes=None):\n    """Avalia as versões. Se `detalhes` for um dict, ele recebe tabela, previsões do teste e importâncias\n    (o painel app_ml.py lê isso do arquivo salvo por main)."""\n    grade = grade or GRADE\n    treino = s[s["ano"].isin(TREINO)].sort_values("inicio")\n    teste = s[s["ano"].isin(TESTE)].sort_values("inicio")\n    real = teste["atendimentos"].to_numpy(dtype=float)\n    normal = regua(treino, teste)\n    ref = metricas(normal, real)\n    ingenuo = metricas(teste["atend_ant_1"].to_numpy(dtype=float), real)\n    avisar(f"treino {len(treino)} distrito-semanas (2015-2021) | teste {len(teste)} (2022-2024)")\n    avisar(f"{\'versão\':38s} {\'valid.\':>7s} | {\'MAE\':>6s} {\'WAPE\':>6s} {\'R²\':>6s} {\'vs régua\':>9s}")\n\n    resultados = {}\n    for nome, (entradas, alvos) in VERSOES.items():\n        previsto, erro_cv, modelos = _versao(treino, teste, entradas, alvos, grade)\n        m = metricas(previsto, real)\n        resultados[nome] = (previsto, erro_cv, modelos, m)\n        avisar(f"{nome:38s} {erro_cv:7.1f} | {m[\'mae\']:6.1f} {m[\'wape\']:6.0%} {m[\'r2\']:6.2f} "\n               f"{1 - m[\'mae\'] / ref[\'mae\']:+9.0%}")\n    avisar(f"{\'régua (o normal)\':38s} {\'\':7s} | {ref[\'mae\']:6.1f} {ref[\'wape\']:6.0%} {ref[\'r2\']:6.2f}")\n    avisar(f"{\'ingênuo (igual à semana passada)\':38s} {\'\':7s} | {ingenuo[\'mae\']:6.1f} {ingenuo[\'wape\']:6.0%} "\n           f"{ingenuo[\'r2\']:6.2f}")\n    avisar("(valid. = erro na validação cruzada do treino, usado para escolher; MAE/WAPE/R² = teste)")\n\n    escolhida = min((n for n in resultados if n != ORIGINAL), key=lambda n: resultados[n][1])\n    previsto, _, modelos, m = resultados[escolhida]\n    aprovado = m["mae"] <= (1 - GANHO_MINIMO) * ref["mae"]\n    avisar(f"\\nEscolhida pela validação: {escolhida}")\n    avisar("Por distrito (teste):")\n    for d, g in teste.assign(prev=previsto, normal=normal).groupby("distrito_codigo"):\n        avisar(f"  DS {d}: real {g[\'atendimentos\'].mean():6.1f}/semana | erro modelo "\n               f"{np.mean(np.abs(g[\'prev\'] - g[\'atendimentos\'])):5.1f} | erro régua "\n               f"{np.nanmean(np.abs(g[\'normal\'] - g[\'atendimentos\'])):5.1f}")\n    entradas, alvos = VERSOES[escolhida]\n    for modelo, alvo in zip(modelos, alvos):\n        imp = sorted(zip(entradas, modelo.feature_importances_), key=lambda p: -p[1])[:6]\n        avisar(f"Importância ({alvo}): " + ", ".join(f"{k} {v:.2f}" for k, v in imp))\n    avisar(f"VEREDITO: {\'APROVADO\' if aprovado else \'NÃO APROVADO\'} (precisa errar pelo menos "\n           f"{GANHO_MINIMO:.0%} menos que a régua)")\n    if detalhes is not None:\n        tabela = [{"versao": n, "validacao": r[1], **r[3]} for n, r in resultados.items()]\n        tabela += [{"versao": "régua (o normal)", "validacao": None, **ref},\n                   {"versao": "ingênuo (igual à semana passada)", "validacao": None, **ingenuo}]\n        detalhes.update({\n            "tabela": tabela, "escolhida": escolhida, "aprovado": bool(aprovado), "ganho_minimo": GANHO_MINIMO,\n            "teste": teste[["distrito_codigo", "inicio", "atendimentos", "atend_ant_1"]].assign(\n                previsto=previsto, normal=normal).reset_index(drop=True),\n            "importancia": {a: dict(zip(VERSOES[escolhida][0], map(float, m.feature_importances_)))\n                            for m, a in zip(modelos, VERSOES[escolhida][1])},\n            "avaliado_em": datetime.now(timezone.utc).isoformat()})\n    return aprovado, m["mae"], ref["mae"]\n\n\ndef treinar_final(s, grade=None):\n    """Treina as versões completa e reduzida com todas as semanas disponíveis."""\n    s = s.sort_values("inicio")\n    modelos = {v: _ajustar(s, VERSOES[v][0], "atendimentos", grade or GRADE) for v in (COMPLETA, REDUZIDA)}\n    normal = s.groupby(["distrito_codigo", "semana"])["atendimentos"].mean()\n    return {"modelos": modelos, "normal": {f"{d}-{w}": float(v) for (d, w), v in normal.items()},\n            "ultima_semana": s["inicio"].max().date().isoformat(),\n            "treinado_em": datetime.now(timezone.utc).isoformat()}\n\n\ndef inicio_da_semana(dia):\n    return dia - timedelta(days=dia.weekday())\n\n\ndef prever(df, pacote, hoje=None, dados_ate=None):\n    """Previsão da semana que contém `hoje` (segunda a domingo), por distrito.\n\n    Acrescenta à tabela diária a semana-alvo vazia: assim `semanal` monta as entradas dela\n    (semanas anteriores, feriados, calendário) do mesmo jeito que no treino."""\n    hoje = hoje or date.today()\n    alvo = pd.Timestamp(inicio_da_semana(hoje))\n    df = df.copy()\n    if df.empty:\n        df = pd.DataFrame(columns=["distrito_codigo", "data", "chuva_dia_mm", "atendimentos_reativos",\n                                   "atendimentos_chuva"])\n    df["data"] = pd.to_datetime(df["data"])\n    df = df[df["data"] < alvo]\n    distritos = sorted(df["distrito_codigo"].unique()) or list(range(1, 9))\n    vazia = pd.DataFrame([{"distrito_codigo": d, "data": alvo + timedelta(days=i), "chuva_dia_mm": 0.0,\n                           "atendimentos_reativos": 0, "atendimentos_chuva": 0}\n                          for d in distritos for i in range(7)])\n    s = semanal(pd.concat([df, vazia], ignore_index=True))\n    s = s[s["inicio"] == alvo]\n    ultimo_dado = pd.Timestamp(dados_ate) if dados_ate else df["data"].max() if len(df) else pd.NaT\n    docs = []\n    for _, linha in s.iterrows():\n        versao = COMPLETA if not np.isnan(linha["atend_ant_1"]) else REDUZIDA\n        entradas = VERSOES[versao][0]\n        valor = float(pacote["modelos"][versao].predict(linha[entradas].to_frame().T.astype(float))[0])\n        normal = pacote["normal"].get(f"{int(linha[\'distrito_codigo\'])}-{int(linha[\'semana\'])}")\n        d = int(linha["distrito_codigo"])\n        docs.append({"distrito_codigo": d, "distrito": nome_distrito(d), "inicio_semana": alvo.date().isoformat(),\n                     "fim_semana": (alvo + timedelta(days=6)).date().isoformat(),\n                     "previsto": round(valor, 1), "normal": round(normal, 1) if normal is not None else None,\n                     "variacao": round(valor / normal - 1, 2) if normal else None,\n                     "versao": versao, "completa": versao == COMPLETA,\n                     "dados_ate": ultimo_dado.date().isoformat() if pd.notna(ultimo_dado) else None,\n                     "gerado_em": datetime.now(timezone.utc).isoformat()})\n    return docs\n\n\ndef _ler_diario(banco, filtro):\n    return pd.DataFrame(list(banco["gold_ml_distrito_dia"].find(\n        filtro, {"_id": 0, "distrito_codigo": 1, "data": 1, "atendimentos_reativos": 1, "atendimentos_chuva": 1,\n                 "chuva_dia_mm": 1})))\n\n\ndef main():\n    argumentos = argparse.ArgumentParser()\n    argumentos.add_argument("--salvar", action="store_true", help="treina com todos os anos e salva o modelo")\n    argumentos.add_argument("--prever", action="store_true", help="grava a previsão da semana atual no banco")\n    argumentos.add_argument("--ate-ano", type=int, help="com --salvar: treina só até este ano (para demonstração)")\n    argumentos.add_argument("--data", help="com --prever: prevê a semana desta data (AAAA-MM-DD), para demonstração")\n    args = argumentos.parse_args()\n    destino = obter_destino()\n    banco = destino.banco\n    arquivo = PASTA_MODELOS / "demanda.joblib"\n\n    if args.salvar:\n        PASTA_MODELOS.mkdir(parents=True, exist_ok=True)\n        filtro = {"ano": {"$gte": 2015, "$lte": args.ate_ano}} if args.ate_ano else {"ano": {"$gte": 2015}}\n        pacote = treinar_final(semanal(_ler_diario(banco, filtro)))\n        joblib.dump(pacote, arquivo)\n        print(f"Modelo salvo em {arquivo} (dados até a semana de {pacote[\'ultima_semana\']})")\n        return\n    if args.prever:\n        if not arquivo.exists():\n            print("Modelo de demanda ainda não treinado: rode python -m ml.demanda --salvar")\n            return\n        recente = list(banco["gold_ml_distrito_dia"].find({}, {"_id": 0, "data": 1}).sort("data", -1).limit(1))\n        hoje = date.fromisoformat(args.data) if args.data else date.today()\n        dados_ate = min(pd.Timestamp(recente[0]["data"]), pd.Timestamp(hoje)) if recente else None\n        desde = datetime.combine(hoje - timedelta(days=60), datetime.min.time())\n        ate = datetime.combine(hoje + timedelta(days=7), datetime.min.time())\n        diario = _ler_diario(banco, {"data": {"$gte": desde, "$lt": ate}})\n        docs = prever(diario, joblib.load(arquivo), hoje=hoje, dados_ate=dados_ate)\n        if args.data:                                          # demonstração: o real já é conhecido\n            real = semanal(diario).set_index(["distrito_codigo", "inicio"])["atendimentos"]\n            for doc in docs:\n                doc["real"] = float(real.get((doc["distrito_codigo"], pd.Timestamp(doc["inicio_semana"])), np.nan))\n                doc["real"] = None if np.isnan(doc["real"]) else doc["real"]\n                doc["demonstracao"] = True\n        destino.carregar(Carga("gold.demanda_previsao", docs))           # substitui a previsão anterior\n        if docs:\n            print(f"Previsão da semana de {docs[0][\'inicio_semana\']}: {len(docs)} distritos, "\n                  f"versão {docs[0][\'versao\']} (dados da Defesa Civil até {docs[0][\'dados_ate\']})")\n        return\n\n    SAIDA.mkdir(parents=True, exist_ok=True)\n    linhas, detalhes = [], {}\n    executar(semanal(_ler_diario(banco, {"ano": {"$gte": 2015, "$lte": 2024}})),\n             avisar=lambda t: (print(t, flush=True), linhas.append(t)), detalhes=detalhes)\n    (SAIDA / "resultado_demanda.txt").write_text("\\n".join(linhas), encoding="utf-8")\n    joblib.dump(detalhes, AVALIACAO)\n    print(f"Detalhes para o painel salvos em {AVALIACAO}")\n\n\nif __name__ == "__main__":\n    main()\n', 'ml/painel.py': '"""Apoio ao painel de demonstração do ML (app_ml.py): leitura do banco e dos arquivos salvos.\n\nFica separado do app para os testes trocarem estas funções por dados de mentira."""\n\nfrom datetime import date, datetime, timedelta\n\nimport joblib\nimport numpy as np\nimport pandas as pd\n\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\nfrom ml import demanda\n\n\ndef _banco():\n    return obter_destino().banco\n\n\ndef ler_diario(desde=None, ate=None):\n    filtro = {"ano": {"$gte": 2015, "$lte": 2024}}\n    if desde or ate:\n        filtro = {"data": {"$gte": desde or datetime(2015, 1, 1), "$lt": ate or datetime(2100, 1, 1)}}\n    return demanda._ler_diario(_banco(), filtro)\n\n\ndef ler_avaliacao():\n    return joblib.load(demanda.AVALIACAO) if demanda.AVALIACAO.exists() else None\n\n\ndef ler_pacote():\n    arquivo = demanda.PASTA_MODELOS / "demanda.joblib"\n    return joblib.load(arquivo) if arquivo.exists() else None\n\n\ndef ler_tabela(nome):\n    return pd.DataFrame(list(_banco()[nome].find({}, {"_id": 0})))\n\n\ndef gravar_simulacao(docs):\n    obter_destino().carregar(Carga("gold.demanda_simulacoes", docs, chaves=("distrito_codigo", "inicio_semana")))\n\n\ndef simular(dia, pacote):\n    """Previsão dos 8 distritos para a semana de `dia`, com o real quando a semana já passou."""\n    inicio = demanda.inicio_da_semana(dia)\n    desde = datetime.combine(inicio - timedelta(days=60), datetime.min.time())\n    ate = datetime.combine(inicio + timedelta(days=7), datetime.min.time())\n    diario = ler_diario(desde, ate)\n    dados_ate = pd.to_datetime(diario["data"]).max() if len(diario) else None\n    docs = demanda.prever(diario, pacote, hoje=dia, dados_ate=min(dados_ate, pd.Timestamp(inicio))\n                          if dados_ate is not None else None)\n    real = demanda.semanal(diario).set_index(["distrito_codigo", "inicio"])["atendimentos"] if len(diario) else {}\n    for d in docs:\n        valor = real.get((d["distrito_codigo"], pd.Timestamp(d["inicio_semana"])), np.nan) if len(real) else np.nan\n        d["real"] = None if pd.isna(valor) else float(valor)\n        d["origem"] = "simulador"\n    return docs\n\n\n# Análises que não passaram na regra fixada antes de rodar (decisões 010 a 013).\nFALHAS = [\n    {"titulo": "Dia crítico por distrito", "decisao": "010",\n     "pergunta": "Prever se amanhã será um dia com alagamento ou deslizamento em cada distrito.",\n     "modelo": "XGBoost classificador, divisão por tempo, TimeSeriesSplit + GridSearch, scale_pos_weight, "\n               "limiar escolhido para recall de 80% na validação.",\n     "regra": "Superar os gatilhos de chuva que a Defesa Civil já usa (F1).",\n     "numeros": [("F1 do modelo", "0,17"), ("F1 dos gatilhos de chuva", "0,33")],\n     "por_que": "Os eventos físicos são raros e o registro de atendimento não mede o evento em si (depende de "\n                "alguém ligar). A chuva acumulada em 7 dias, a entrada mais forte, já está nos gatilhos simples: "\n                "o modelo não acrescenta informação além da regra.",\n     "aprendizado": "O alvo mudou três vezes (p95, pico 3× a rotina, eventos físicos), sempre registrado. "\n                    "Testar contra a regra atual, e não contra \'chutar sempre não\', evitou um 95% de acurácia enganoso."},\n    {"titulo": "Chuva × maré", "decisao": "011",\n     "pergunta": "A maré alta junto com a chuva aumenta o risco de alagamento no Recife?",\n     "modelo": "O mesmo modelo com e sem maré; diferença de precisão média com intervalo de confiança "\n               "por bootstrap de dias.",\n     "regra": "Intervalo de confiança da melhora inteiro acima de zero.",\n     "numeros": [("Maré do dia: melhora", "IC −0,038 a +0,005"), ("Maré na hora do pico: melhora", "+0,019 (IC −0,008 a +0,058)"),\n                 ("Bootstrap a favor", "92%")],\n     "por_que": "Não há marégrafo nem medição de nível de rio pública no Recife: a maré é calculada (análise "\n                "harmônica, validada com o GTSM do Copernicus, correlação 0,88). Chuvas fortes que coincidem com "\n                "maré alta são poucas, então o intervalo ainda cruza o zero.",\n     "aprendizado": "Resultado: sinal provável, não confirmado. A maré da hora do pico importa mais que a do dia. "\n                    "Pedido de dados ao BNDO (Marinha) e análise por bairros sensíveis como próximos passos."},\n    {"titulo": "Eventos na região metropolitana (REINDESC)", "decisao": "012",\n     "pergunta": "Prever dias com desastre registrado no REINDESC nos 14 municípios da RMR.",\n     "modelo": "XGBoost com ERA5-Land e CEMADEN, contra um controle sem chuva e contra os gatilhos.",\n     "regra": "Superar os gatilhos de chuva no F1.",\n     "numeros": [("Precisão média: modelo × controle", "0,113 × 0,015"), ("F1: modelo × gatilhos", "0,08 × 0,09"),\n                 ("Gatilhos atuais avisam", "47% no Recife, 76% na região")],\n     "por_que": "São só 825 ocorrências em 10 anos: com tão poucos positivos, nenhum limiar dá um alarme sim/não "\n                "confiável. Mas o modelo ORDENA bem os dias por risco (venceu o controle em todos os anos de 2020 a 2026).",\n     "aprendizado": "Não serve como alarme, serve como índice de risco de 0 a 1. E mostrou um achado prático: os "\n                    "gatilhos atuais deixam passar metade dos eventos do Recife."},\n    {"titulo": "Dengue com clima", "decisao": "013",\n     "pergunta": "Temperatura, umidade e chuva ajudam a prever os casos de dengue 4 semanas à frente?",\n     "modelo": "XGBoost com e sem as variáveis de clima (InfoDengue + Open-Meteo).",\n     "regra": "Pelo menos 5% menos erro com clima.",\n     "numeros": [("Erro com clima", "0,397"), ("Erro sem clima", "0,399")],\n     "por_que": "Os casos das semanas anteriores (importância 0,57 + 0,15) já carregam o efeito do clima e da "\n                "sazonalidade. O clima não traz informação nova para 4 semanas à frente.",\n     "aprendizado": "Coerente com a análise chuva→dengue da etapa 4, que também não achou efeito além da sazonalidade."},\n    {"titulo": "Perfis de bairro (agrupamento)", "decisao": "013",\n     "pergunta": "Os 92 bairros formam grupos de risco distintos?",\n     "modelo": "K-means com taxas por 10 mil habitantes (cortadas no p95), escolha de k pela silhueta, "\n               "mínimo de 3 bairros por grupo.",\n     "regra": "Grupos interpretáveis e silhueta que indique estrutura.",\n     "numeros": [("Silhueta", "0,24"), ("Grupos", "encosta 24 · comunidades/alagamento 32 · baixo risco 36")],\n     "por_que": "Pela escala de Kaufman & Rousseeuw, até 0,25 não há estrutura substancial: o risco varia de forma "\n                "contínua entre os bairros, sem fronteiras claras. Alguns \'Altos\' caíram em baixo risco, "\n                "provavelmente por como o nome do bairro aparece nos registros.",\n     "aprendizado": "Usado só como descrição no mapa, para validar com a Mariana (Vigidesastres), não como classificação."},\n]\n', 'app_ml.py': '"""Painel de demonstração do Machine Learning do Vigidesastres (no formato da Aula 12 de AVD).\n\nSeparado do site em Django: é para apresentar o modelo, não para a equipe da Vigidesastres.\n\nAntes de abrir:\n    python -m ml.demanda                         avaliação (gera analises/ml/saida/demanda_avaliacao.joblib)\n    python -m ml.demanda --salvar --ate-ano 2023 modelo para o simulador (não viu 2024)\nAbrir:\n    streamlit run app_ml.py\n"""\n\nfrom datetime import date\n\nimport pandas as pd\nimport plotly.express as px\nimport streamlit as st\n\nfrom dominio.distritos import nome_distrito\nfrom ml import demanda, painel\n\nst.set_page_config(page_title="ML · Vigidesastres", layout="wide")\nst.title("Vigidesastres · Machine Learning")\nst.caption("Previsão da demanda semanal de atendimentos da Defesa Civil por distrito sanitário do Recife")\n\n\n@st.cache_data(ttl=600)\ndef carregar_semanal():\n    return demanda.semanal(painel.ler_diario())\n\n\n@st.cache_data(ttl=600)\ndef carregar_avaliacao():\n    return painel.ler_avaliacao()\n\n\n@st.cache_resource\ndef carregar_pacote():\n    return painel.ler_pacote()\n\n\naba_dados, aba_modelo, aba_simulador, aba_gold, aba_falhas = st.tabs(\n    ["Os dados", "O modelo", "Simulador", "Previsões salvas", "O que não passou"])\n\n# ---------------------------------------------------------------- Os dados\nwith aba_dados:\n    s = carregar_semanal()\n    s["distrito"] = s["distrito_codigo"].map(nome_distrito)\n    recife = s.groupby("inicio", as_index=False)["atendimentos"].sum()\n    c1, c2, c3 = st.columns(3)\n    c1.metric("Distrito-semanas", f"{len(s):,}".replace(",", "."))\n    c2.metric("Atendimentos por semana (Recife)", f"{recife[\'atendimentos\'].mean():.0f}")\n    c3.metric("Período", f"{s[\'inicio\'].min():%Y} a {s[\'inicio\'].max():%Y}")\n    st.caption("Fonte: atendimentos reativos da Defesa Civil (dados abertos do Recife) e chuva do CEMADEN/INMET, "\n               "na tabela gold.ml_distrito_dia.")\n\n    st.plotly_chart(px.line(recife, x="inicio", y="atendimentos", title="Atendimentos por semana no Recife",\n                            labels={"inicio": "semana", "atendimentos": "atendimentos"}))\n    c1, c2 = st.columns(2)\n    por_mes = s.groupby("mes", as_index=False)["atendimentos"].mean()\n    c1.plotly_chart(px.bar(por_mes, x="mes", y="atendimentos", title="Média por distrito e semana, por mês",\n                           labels={"mes": "mês", "atendimentos": "atendimentos/semana"}))\n    c2.plotly_chart(px.box(s.sort_values("distrito_codigo"), x="distrito", y="atendimentos",\n                           title="Atendimentos por semana em cada distrito"))\n    st.plotly_chart(px.scatter(s, x="chuva_semana_anterior_mm", y="atendimentos", color="distrito", opacity=0.4,\n                               title="Chuva da semana anterior × atendimentos da semana",\n                               labels={"chuva_semana_anterior_mm": "chuva da semana anterior (mm)"}))\n    st.caption("A chuva sozinha explica pouco: semanas com a mesma chuva têm demandas muito diferentes. "\n               "O que mais pesa é o patamar de cada distrito e a época do ano.")\n\n# ---------------------------------------------------------------- O modelo\nwith aba_modelo:\n    av = carregar_avaliacao()\n    if av is None:\n        st.warning("Avaliação ainda não salva. Rode `python -m ml.demanda`.")\n    else:\n        tabela = pd.DataFrame(av["tabela"]).set_index("versao")\n        esc, regua = tabela.loc[av["escolhida"]], tabela.loc["régua (o normal)"]\n        ingenuo = tabela.loc["ingênuo (igual à semana passada)"]\n        c1, c2, c3, c4 = st.columns(4)\n        c1.metric("Erro (WAPE) no teste", f"{esc[\'wape\']:.0%}")\n        c2.metric("R² no teste", f"{esc[\'r2\']:.2f}")\n        c3.metric("Menos erro que a régua", f"{1 - esc[\'mae\'] / regua[\'mae\']:.0%}")\n        c4.metric("Menos erro que \'semana passada\'", f"{1 - esc[\'mae\'] / ingenuo[\'mae\']:.0%}")\n        (st.success if av["aprovado"] else st.error)(\n            f"Versão escolhida: **{av[\'escolhida\']}** · {\'APROVADO\' if av[\'aprovado\'] else \'NÃO APROVADO\'} "\n            f"(regra fixada antes de rodar: errar pelo menos {av[\'ganho_minimo\']:.0%} menos que a régua no teste 2022-2024)")\n\n        st.subheader("Versões testadas")\n        mostrar = tabela.rename(columns={"validacao": "erro na validação (treino)", "mae": "MAE (teste)",\n                                         "wape": "WAPE (teste)", "r2": "R² (teste)"})\n        st.dataframe(mostrar.style.format({"erro na validação (treino)": "{:.1f}", "MAE (teste)": "{:.1f}",\n                                           "WAPE (teste)": "{:.0%}", "R² (teste)": "{:.2f}"}, na_rep="—"))\n        st.info("**Como ler.** A versão 0 usava a chuva da própria semana, que ninguém sabe na segunda-feira: era "\n                "vazamento de dados. Corrigida (versão 1), o ganho caiu de 11% para 6%. A demanda das semanas "\n                "anteriores (versão 2) trouxe o maior salto. A escolha entre 1 e 4 é feita pelo erro na validação "\n                "do treino, nunca pelo teste.")\n\n        teste = av["teste"].copy()\n        teste["distrito"] = teste["distrito_codigo"].map(nome_distrito)\n        escolhido = st.selectbox("Distrito", [nome_distrito(c) for c in sorted(teste["distrito_codigo"].unique())])\n        g = teste[teste["distrito"] == escolhido].melt(id_vars="inicio", value_vars=["atendimentos", "previsto", "normal"],\n                                                       var_name="série", value_name="valor")\n        st.plotly_chart(px.line(g, x="inicio", y="valor", color="série",\n                                title=f"{escolhido}: real × previsto × normal no teste (2022-2024)",\n                                labels={"inicio": "semana", "valor": "atendimentos"}))\n\n        c1, c2 = st.columns(2)\n        erros = teste.assign(modelo=(teste["previsto"] - teste["atendimentos"]).abs(),\n                             régua=(teste["normal"] - teste["atendimentos"]).abs())\n        erros = erros.groupby("distrito", as_index=False)[["modelo", "régua"]].mean().melt(\n            id_vars="distrito", var_name="quem", value_name="erro")\n        c1.plotly_chart(px.bar(erros, x="distrito", y="erro", color="quem", barmode="group",\n                               title="Erro médio por semana, por distrito", labels={"erro": "atendimentos"}))\n        imp = pd.Series(next(iter(av["importancia"].values()))).nlargest(8).sort_values()\n        c2.plotly_chart(px.bar(imp, orientation="h", title="Entradas mais importantes",\n                               labels={"value": "importância", "index": ""}))\n\n# ---------------------------------------------------------------- Simulador\nwith aba_simulador:\n    pacote = carregar_pacote()\n    if pacote is None:\n        st.warning("Modelo ainda não salvo. Rode `python -m ml.demanda --salvar --ate-ano 2023`.")\n    else:\n        st.caption(f"Modelo treinado com dados até a semana de {pacote[\'ultima_semana\']}. "\n                   "Para uma demonstração honesta, escolha semanas depois disso.")\n        with st.form("semana"):\n            c1, c2 = st.columns(2)\n            dia = c1.date_input("Um dia da semana a prever", value=date(2024, 5, 20))\n            distrito = c2.selectbox("Distrito em destaque", list(range(1, 9)), format_func=nome_distrito, index=6)\n            gravar = st.checkbox("Gravar a previsão na camada gold")\n            enviar = st.form_submit_button("Prever")\n        if enviar:\n            if pd.Timestamp(demanda.inicio_da_semana(dia)) <= pd.Timestamp(pacote["ultima_semana"]):\n                st.warning("O modelo já viu essa semana no treino: o acerto aqui não vale como teste.")\n            docs = painel.simular(dia, pacote)\n            d = next(x for x in docs if x["distrito_codigo"] == distrito)\n            c1, c2, c3 = st.columns(3)\n            c1.metric(f"Previsto · {d[\'distrito\']}", f"{d[\'previsto\']:.0f}",\n                      None if d["variacao"] is None else f"{d[\'variacao\']:+.0%} do normal", delta_color="off")\n            c2.metric("Normal da época", "—" if d["normal"] is None else f"{d[\'normal\']:.0f}")\n            c3.metric("Real", "semana ainda não aconteceu" if d["real"] is None else f"{d[\'real\']:.0f}")\n            if not d["completa"]:\n                st.info(f"Sem os atendimentos da semana anterior (dados até {d[\'dados_ate\']}): usada a versão "\n                        "reduzida, só calendário e chuva.")\n            todos = pd.DataFrame(docs).melt(id_vars="distrito", value_vars=["previsto", "normal", "real"],\n                                             var_name="série", value_name="atendimentos")\n            st.plotly_chart(px.bar(todos, x="distrito", y="atendimentos", color="série", barmode="group",\n                                   title=f"Semana de {docs[0][\'inicio_semana\']}: todos os distritos"))\n            if gravar:\n                painel.gravar_simulacao(docs)\n                st.info("Previsão gravada em gold.demanda_simulacoes.")\n\n# ---------------------------------------------------------------- Previsões salvas\nwith aba_gold:\n    for titulo, tabela in (("Previsão da semana (a que aparece no Calendário do site)", "gold_demanda_previsao"),\n                           ("Previsões gravadas pelo simulador", "gold_demanda_simulacoes")):\n        st.subheader(titulo)\n        try:\n            gold = painel.ler_tabela(tabela)\n        except Exception:\n            gold = pd.DataFrame()\n        if gold.empty:\n            st.info("Nada gravado ainda. Use o simulador ou rode `python -m ml.demanda --prever`.")\n            continue\n        colunas = [c for c in ["inicio_semana", "distrito", "previsto", "normal", "real", "versao", "gerado_em"]\n                   if c in gold]\n        st.metric("Linhas", len(gold))\n        st.dataframe(gold[colunas].sort_values(colunas[:2]), key=f"tabela_{tabela}")\n        if "real" in gold and gold["real"].notna().any():\n            com_real = gold.dropna(subset=["real"])\n            st.plotly_chart(px.scatter(com_real, x="real", y="previsto", color="distrito",\n                                       title="Previsto × real (quanto mais perto da diagonal, melhor)"),\n                            key=f"dispersao_{tabela}")\n\n# ---------------------------------------------------------------- O que não passou\nwith aba_falhas:\n    st.write("Cada análise teve uma **regra de aprovação fixada antes de rodar** e uma comparação com uma "\n             "alternativa simples. Estas não passaram; o resultado negativo também é registrado "\n             "(`docs/decisoes/`).")\n    for f in painel.FALHAS:\n        with st.container(border=True):\n            st.subheader(f"{f[\'titulo\']} · decisão {f[\'decisao\']}")\n            st.write(f"**Pergunta:** {f[\'pergunta\']}")\n            st.write(f"**Modelo:** {f[\'modelo\']}")\n            st.write(f"**Regra de aprovação:** {f[\'regra\']}")\n            for coluna, (rotulo, valor) in zip(st.columns(len(f["numeros"])), f["numeros"]):\n                coluna.metric(rotulo, valor)\n            st.write(f"**Por que não passou:** {f[\'por_que\']}")\n            st.write(f"**O que aprendemos:** {f[\'aprendizado\']}")\n', 'tests/test_app_ml.py': 'from datetime import date\nfrom pathlib import Path\n\nimport pandas as pd\nimport pytest\n\nfrom ml import demanda, painel\nfrom tests.test_demanda import GRADE, _diario\n\nst_testing = pytest.importorskip("streamlit.testing.v1")\n\n\n@pytest.fixture\ndef painel_falso(monkeypatch):\n    diario = _diario()\n    s = demanda.semanal(diario)\n    detalhes = {}\n    demanda.executar(s, GRADE, avisar=lambda t: None, detalhes=detalhes)\n    pacote = demanda.treinar_final(s[s["ano"] <= 2023], GRADE)\n    gravado = []\n\n    def ler_diario(desde=None, ate=None):\n        d = diario.copy()\n        d["data"] = pd.to_datetime(d["data"])\n        if desde:\n            d = d[(d["data"] >= desde) & (d["data"] < ate)]\n        return d\n\n    monkeypatch.setattr(painel, "ler_diario", ler_diario)\n    monkeypatch.setattr(painel, "ler_avaliacao", lambda: detalhes)\n    monkeypatch.setattr(painel, "ler_pacote", lambda: pacote)\n    monkeypatch.setattr(painel, "gravar_simulacao", lambda docs: gravado.extend(docs))\n    monkeypatch.setattr(painel, "ler_tabela", lambda nome: pd.DataFrame(gravado))\n    return detalhes, gravado\n\n\ndef test_painel_abre_e_simula(painel_falso):\n    detalhes, gravado = painel_falso\n    assert {"tabela", "escolhida", "teste", "importancia"} <= detalhes.keys()\n    at = st_testing.AppTest.from_file(str(Path(__file__).resolve().parents[1] / "app_ml.py"), default_timeout=120).run()\n    assert not at.exception\n    rotulos = [m.label for m in at.metric]\n    assert "Distrito-semanas" in rotulos and "Erro (WAPE) no teste" in rotulos and "Silhueta" in rotulos\n    at.selectbox[1].set_value(7)\n    at.checkbox[0].check()\n    at.button[0].click().run()\n    assert not at.exception\n    assert len(gravado) == 2 and all(d["real"] is not None for d in gravado)   # 2024: real conhecido\n    assert any("gravada" in i.value for i in at.info)\n\n\ndef test_simular_semana_futura_sem_real(painel_falso):\n    docs = painel.simular(date(2026, 11, 19), painel.ler_pacote())\n    assert docs and all(d["real"] is None and not d["completa"] for d in docs)\n'}

raiz = Path.cwd()
